/**
 * @param {number} n
  * @param {number} k
   * @param {number} m
    * @param {number[]} time
     * @param {number[]} mul
      * @return {number}
       */
       var minTime = function(n, k, m, time, mul) {
           if (n > 1 && k === 1) return -1;
           
               const fullMask = (1 << n) - 1;
                   const dist = Array.from({length: fullMask + 1}, () => new Float64Array(m).fill(Infinity));
                       dist[0][0] = 0;
                       
                           class MinHeap {
                                   constructor() { this.data = []; }
                                           push(val) {
                                                       this.data.push(val);
                                                                   this.up(this.data.length - 1);
                                                                           }
                                                                                   pop() {
                                                                                               if (this.data.length === 0) return null;
                                                                                                           const top = this.data[0];
                                                                                                                       const bottom = this.data.pop();
                                                                                                                                   if (this.data.length > 0) {
                                                                                                                                                   this.data[0] = bottom;
                                                                                                                                                                   this.down(0);
                                                                                                                                                                               }
                                                                                                                                                                                           return top;
                                                                                                                                                                                                   }
                                                                                                                                                                                                           up(i) {
                                                                                                                                                                                                                       while (i > 0) {
                                                                                                                                                                                                                                       const p = (i - 1) >> 1;
                                                                                                                                                                                                                                                       if (this.data[i][0] >= this.data[p][0]) break;
                                                                                                                                                                                                                                                                       [this.data[i], this.data[p]] = [this.data[p], this.data[i]];
                                                                                                                                                                                                                                                                                       i = p;
                                                                                                                                                                                                                                                                                                   }
                                                                                                                                                                                                                                                                                                           }
                                                                                                                                                                                                                                                                                                                   down(i) {
                                                                                                                                                                                                                                                                                                                               const len = this.data.length;
                                                                                                                                                                                                                                                                                                                                           while ((i << 1) + 1 < len) {
                                                                                                                                                                                                                                                                                                                                                           let left = (i << 1) + 1;
                                                                                                                                                                                                                                                                                                                                                                           let right = left + 1;
                                                                                                                                                                                                                                                                                                                                                                                           let best = i;
                                                                                                                                                                                                                                                                                                                                                                                                           if (this.data[left][0] < this.data[best][0]) best = left;
                                                                                                                                                                                                                                                                                                                                                                                                                           if (right < len && this.data[right][0] < this.data[best][0]) best = right;
                                                                                                                                                                                                                                                                                                                                                                                                                                           if (best === i) break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                           [this.data[i], this.data[best]] = [this.data[best], this.data[i]];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                           i = best;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       isEmpty() { return this.data.length === 0; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const pq = new MinHeap();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   pq.push([0, 0, 0]); 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       const maxTime = new Float64Array(fullMask + 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const popCount = new Int32Array(fullMask + 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               for (let i = 1; i <= fullMask; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       let maxT = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               let c = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       for (let j = 0; j < n; j++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if ((i & (1 << j)) !== 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   maxT = Math.max(maxT, time[j]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   c++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               maxTime[i] = maxT;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       popCount[i] = c;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               let minAns = Infinity;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   while (!pq.isEmpty()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const [cost, mask, stage] = pq.pop();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (cost > dist[mask][stage]) continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const avail = fullMask ^ mask; 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           for (let group = avail; group > 0; group = (group - 1) & avail) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       if (popCount[group] > k) continue; 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const d = maxTime[group] * mul[stage];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const nextMask = mask | group;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (nextMask === fullMask) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (cost + d < minAns) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               minAns = cost + d;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       const stagePrime = (stage + Math.floor(d)) % m;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   for (let j = 0; j < n; j++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if ((nextMask & (1 << j)) !== 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       const ret = time[j] * mul[stagePrime];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const stageDoublePrime = (stagePrime + Math.floor(ret)) % m;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const finalMask = nextMask ^ (1 << j); 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const nextCost = cost + d + ret;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       if (nextCost < dist[finalMask][stageDoublePrime]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               dist[finalMask][stageDoublePrime] = nextCost;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       pq.push([nextCost, finalMask, stageDoublePrime]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       return minAns === Infinity ? -1 : minAns;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }; 